ediciones.reemplazo:
// Estado de la cola de seguimientos de una sesión.
seg_fila: `SELECT * FROM hpf_seguimientos WHERE session_id = $1`,

// El evento que el lead eligió, persistido por W6. Es la memoria que antes no
// existía: sin ella el agente Products re-adivinaba el evento en cada turno y
// derrapaba a "Boda", así que una conversación de XV recibía fichas de Boda.
estado_sesion: `SELECT session_id, evento, actualizado_at
                FROM hpf_estado_sesion WHERE session_id LIKE $1
                ORDER BY actualizado_at DESC LIMIT 25`,
